export function ListHeader({
  title = "{{title}}",
  count = {{count}},
  layout = "{{layout}}",
  accent = "{{accent}}",
  sticky = {{sticky}},
}) {
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", background: "#FAF7F2", maxWidth: 300, width: 300, borderRadius: 12, boxSizing: "border-box", overflow: "hidden", border: "1px solid #24143014" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "12px 14px", borderBottom: `2px solid ${accent}`, position: sticky ? "sticky" : "static", top: sticky ? 0 : undefined, background: sticky ? "#FAF7F2" : "transparent" }}>
        <h3 style={{ margin: 0, fontSize: 14, fontWeight: 700, flex: 1 }}>{title}{sticky && <span aria-label="Sticky"> 📌</span>}</h3>
        {layout === "with-count" && <span style={{ fontSize: 12, color: "#241430a0" }}>{count} items</span>}
        {layout === "with-action" && <button type="button" style={{ background: accent, color: "#241430", border: "none", borderRadius: 6, padding: "5px 10px", font: "inherit", fontWeight: 600, cursor: "pointer" }}>Add</button>}
      </div>
      <ul style={{ listStyle: "none", margin: 0, padding: "8px 14px" }}>
        <li style={{ padding: "6px 0" }}>Alicia Ferreira</li>
        <li style={{ padding: "6px 0" }}>Ben Sato</li>
        <li style={{ padding: "6px 0" }}>Charu Deshpande</li>
      </ul>
    </div>
  );
}
